              "<strong>平方根的分组错误。</strong>错误：√c² − a²（等于 c − a）。正确：√(c² − a²)，整个差值都在根号内。",
              "<strong>输入 a ≥ c。</strong>已知的直角边不能等于或超过斜边。正确做法：计算前验证 c > a。",
